async function handleGetCourse(request, env2, courseId) {
  try {
    const course = await env2.DB.prepare("SELECT * FROM Courses WHERE id = ?").bind(courseId).first();
    if (!course)
      return new Response(JSON.stringify({ error: "Course not found" }), {
        status: 404
      });
    let isEnrolled = false;
    let isAdmin = false;
    let paymentStatus = null;
    let enrollmentStatus = null;
    let progress = 0;
    let hasActiveSubscription = false;
    let subscriptionCourseAccess = false;
    let walletBalanceCrs = null;
    const token = getCookie(request, "session");
    if (token) {
      try {
        const jwtSecret = await getSecret(env2, "JWT_SECRET");
        if (!jwtSecret) throw new Error("JWT_SECRET missing");
        const payload = await verifyJWT(token, jwtSecret, env2.ENVIRONMENT);
        if (payload.role === "admin" || payload.role === "teacher")
          isAdmin = true;
        if (payload.role === "student") {
          walletBalanceCrs = await getWalletBalance(env2, payload.sub);
          const profile3 = await getUserAccessProfile(payload.sub, env2);
          hasActiveSubscription = profile3.hasActiveSub;
          subscriptionCourseAccess = userAccessProfileAllowsCourse(profile3, courseId);
        }
        const existing = await env2.DB.prepare(
          `SELECT payment_status, status, progress
           FROM Enrollments
           WHERE user_id = ? AND course_id = ?
           ORDER BY purchased_at DESC
           LIMIT 1`
        ).bind(payload.sub, courseId).first();
        if (existing) {
          isEnrolled = true;
          paymentStatus = existing.payment_status || null;
          enrollmentStatus = existing.status || null;
          progress = existing.progress ?? 0;
        }
      } catch (e) {
      }
    }
    return new Response(JSON.stringify({
      course,
      isEnrolled,
      isAdmin,
      paymentStatus,
      enrollmentStatus,
      progress,
      hasActiveSubscription,
      subscriptionCourseAccess,
      walletBalance: walletBalanceCrs
    }), {
      status: 200,
      headers: { "Content-Type": "application/json" }
    });
  } catch (error4) {
    return handleGlobalError(error4, "Course.Get", env2, request);
  }
}
