async function handleGetBook(request, env2, bookId) {
  try {
    const book = await env2.DB.prepare("SELECT * FROM Books WHERE id = ?").bind(bookId).first();
    if (!book)
      return new Response(JSON.stringify({ error: "Book not found" }), {
        status: 404,
        headers: { "Content-Type": "application/json" }
      });
    const [lessonsRes, linkedCoursesRes] = await Promise.all([
      env2.DB.prepare(
        `SELECT l.*, b.name as batch_name, b.name_hi as batch_name_hi
         FROM Lessons l
         LEFT JOIN Batches b ON l.batch_id = b.id
         WHERE l.book_id = ? ORDER BY l.order_index ASC`
      ).bind(bookId).all(),
      env2.DB.prepare(
        "SELECT c.*, cb.order_index as link_order FROM Courses c JOIN CourseBooks cb ON c.id = cb.course_id WHERE cb.book_id = ? ORDER BY cb.order_index ASC"
      ).bind(bookId).all()
    ]);
    let isEnrolled = false;
    let paymentStatus = null;
    let completedLessonIds = [];
    const token = getCookie(request, "session");
    if (token) {
      try {
        const jwtSecret = await getSecret(env2, "JWT_SECRET");
        if (jwtSecret) {
          const payload = await verifyJWT(token, jwtSecret, env2.ENVIRONMENT);
          const userId = payload.sub;
          const enrollment = await env2.DB.prepare(
            "SELECT payment_status FROM Enrollments WHERE user_id = ? AND book_id = ? AND status IN ('active', 'completed') LIMIT 1"
          ).bind(userId, bookId).first();
          if (enrollment) {
            isEnrolled = true;
            paymentStatus = enrollment.payment_status;
          }
          if (!isEnrolled && linkedCoursesRes.results.length > 0) {
            const courseIds = linkedCoursesRes.results.map((c) => c.id);
            const placeholders = courseIds.map(() => "?").join(",");
            const courseEnr = await env2.DB.prepare(
              `SELECT payment_status FROM Enrollments WHERE user_id = ? AND course_id IN (${placeholders}) AND status IN ('active', 'completed') LIMIT 1`
            ).bind(userId, ...courseIds).first();
            if (courseEnr) {
              isEnrolled = true;
              paymentStatus = courseEnr.payment_status;
            }
          }
          if (!isEnrolled) {
            for (const c of linkedCoursesRes.results) {
              if (await userHasSubscriptionCourseAccess(userId, c.id, env2)) {
                isEnrolled = true;
                paymentStatus = "paid";
                break;
              }
            }
          }
          const completedRes = await env2.DB.prepare(
            "SELECT lesson_id FROM CompletedLessons WHERE user_id = ? AND lesson_id IN (SELECT id FROM Lessons WHERE book_id = ?)"
          ).bind(userId, bookId).all();
          completedLessonIds = completedRes.results?.map((r2) => r2.lesson_id) || [];
        }
      } catch (e) {
      }
    }
    return new Response(JSON.stringify({
      book,
      lessons: lessonsRes.results,
      courses: linkedCoursesRes.results,
      isEnrolled,
      paymentStatus,
      completedLessonIds
    }), {
      status: 200,
      headers: { "Content-Type": "application/json" }
    });
  } catch (error4) {
    return handleGlobalError(error4, "Book.Get", env2, request);
  }
}
