async function handleCheckDuplicateSubmission(request, env2, slug) {
  try {
    const url = new URL(request.url);
    const email = url.searchParams.get("email");
    const phone = url.searchParams.get("phone");
    if (!email && !phone)
      return new Response(JSON.stringify({ exists: false }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    const template = await env2.DB.prepare(
      "SELECT id FROM FormTemplates WHERE slug = ?"
    ).bind(slug).first();
    if (!template)
      return new Response(JSON.stringify({ error: "Form not found" }), {
        status: 404
      });
    let exists = false;
    if (email) {
      const existingEmail = await env2.DB.prepare(
        "SELECT id FROM FormSubmissions WHERE template_id = ? AND email = ?"
      ).bind(template.id, email).first();
      if (existingEmail) exists = true;
    }
    if (!exists && phone) {
      const phoneSubmissions = await env2.DB.prepare(
        "SELECT data_json FROM FormSubmissions WHERE template_id = ?"
      ).bind(template.id).all();
      for (const sub of phoneSubmissions.results) {
        try {
          const data = JSON.parse(sub.data_json);
          const storedPhone = (data.phone || data.mobile || "").toString().trim();
          if (storedPhone === phone) {
            exists = true;
            break;
          }
        } catch {
        }
      }
    }
    return new Response(JSON.stringify({ exists }), {
      status: 200,
      headers: { "Content-Type": "application/json" }
    });
  } catch (error4) {
    return handleGlobalError(error4, "Form.CheckDuplicate", env2, request);
  }
}
