async function handleAdminCancelIndividualBooking(request, env2, bookingId) {
  try {
    await requireAdmin(request, env2);
    const booking = await env2.DB.prepare(
      `SELECT * FROM IndividualBookings WHERE id = ?`
    ).bind(bookingId).first();
    if (!booking) {
      return new Response(JSON.stringify({ error: "Booking not found" }), { status: 404 });
    }
    if (booking.status !== "scheduled") {
      return new Response(JSON.stringify({ error: "Only scheduled bookings can be cancelled" }), { status: 400 });
    }
    if (booking.amount_charged_rupees > 0 && !booking.amount_refunded_rupees) {
      await addToWallet(
        env2,
        booking.student_id,
        booking.amount_charged_rupees,
        "individual_class_refund",
        "individual_booking",
        bookingId
      );
    }
    if (booking.live_session_id) {
      await env2.DB.prepare(
        `UPDATE LiveSessions SET status = 'ended' WHERE id = ? AND status != 'ended'`
      ).bind(booking.live_session_id).run();
    }
    await env2.DB.prepare(
      `UPDATE IndividualBookings SET status = 'cancelled', amount_refunded_rupees = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?`
    ).bind(booking.amount_charged_rupees > 0 ? booking.amount_charged_rupees : 0, bookingId).run();
    removeEventFromGoogle(env2, "IndividualBookings", bookingId).catch((e) => console.error("[GC] Booking remove failed", e));
    return new Response(JSON.stringify({ success: true, message: "Booking cancelled, credits refunded" }), {
      status: 200,
      headers: { "Content-Type": "application/json" }
    });
  } catch (error4) {
    return handleGlobalError(error4, "Individual.AdminCancel", env2, request);
  }
}
