async function handleRazorpayVerifyTopupPayment(request, env2) {
  try {
    const payload = await requireAuth(request, env2);
    const body = await request.json();
    const { razorpay_order_id, razorpay_payment_id, razorpay_signature } = body;
    if (!razorpay_order_id || !razorpay_payment_id || !razorpay_signature) {
      return new Response(
        JSON.stringify({ error: "Incomplete payment details" }),
        { status: 400 }
      );
    }
    const keySecret = await getSecret(env2, "RAZORPAY_KEY_SECRET", false);
    if (!keySecret) {
      return new Response(
        JSON.stringify({ error: "Payment gateway not configured" }),
        { status: 503 }
      );
    }
    const encoder = new TextEncoder();
    const data = `${razorpay_order_id}|${razorpay_payment_id}`;
    const key = await crypto.subtle.importKey(
      "raw",
      encoder.encode(keySecret),
      { name: "HMAC", hash: "SHA-256" },
      false,
      ["sign"]
    );
    const signatureBuf = await crypto.subtle.sign(
      "HMAC",
      key,
      encoder.encode(data)
    );
    const generatedSignature = Array.from(new Uint8Array(signatureBuf)).map((b) => b.toString(16).padStart(2, "0")).join("");
    if (!timingSafeEqual(generatedSignature, razorpay_signature)) {
      await env2.DB.prepare(
        "UPDATE Transactions SET status = ? WHERE razorpay_order_id = ?"
      ).bind("failed", razorpay_order_id).run();
      return new Response(
        JSON.stringify({ error: "Invalid payment signature" }),
        { status: 400 }
      );
    }
    const tx = await env2.DB.prepare(
      `UPDATE Transactions SET status = 'successful', razorpay_payment_id = ?, razorpay_signature = ? WHERE razorpay_order_id = ? AND status = 'created' AND razorpay_payment_id IS NULL RETURNING *`
    ).bind(razorpay_payment_id, razorpay_signature, razorpay_order_id).first();
    if (!tx) {
      return new Response(
        JSON.stringify({ error: "Transaction not found or already processed" }),
        { status: 400 }
      );
    }
    await env2.DB.prepare(`UPDATE CouponRedemptions SET status = 'successful', redeemed_at = CURRENT_TIMESTAMP WHERE transaction_id IN (SELECT id FROM Transactions WHERE razorpay_order_id = ?)`).bind(razorpay_order_id).run();
    const amountInr = Number(tx.credits_added || Number(tx.amount_rupees) || 0);
    const wallet = await addToWallet(
      env2,
      payload.sub,
      amountInr,
      "purchase",
      tx.related_id ? "credit_pack" : "razorpay_order",
      tx.related_id || razorpay_order_id
    );
    return new Response(
      JSON.stringify({ success: true, balance_rupees: wallet.balance_rupees }),
      {
        status: 200,
        headers: { "Content-Type": "application/json" }
      }
    );
  } catch (error4) {
    return handleGlobalError(error4, "Razorpay.VerifyTopupPayment", env2, request);
  }
}
