async function handleLiveSignaling(request, env2) {
  try {
    const payload = await requireAuth(request, env2);
    const url = new URL(request.url);
    const sessionId = url.searchParams.get("sessionId");
    if (!sessionId)
      return new Response(JSON.stringify({ error: "sessionId required" }), {
        status: 400
      });
    if (request.method === "POST") {
      const { type, data } = await request.json();
      const id = generateCustomId("YA-SIG");
      await env2.DB.prepare(
        "INSERT INTO LiveSignaling (id, session_id, user_id, type, data) VALUES (?, ?, ?, ?, ?)"
      ).bind(id, sessionId, payload.sub, type, JSON.stringify(data)).run();
      if (payload.role === "student" && type === "offer_request") {
        const sessionCourse = await env2.DB.prepare(
          `SELECT course_id FROM LiveSessions WHERE id = ?`
        ).bind(sessionId).first();
        if (sessionCourse) {
          const isEnrolled = await env2.DB.prepare(
            `SELECT id FROM Enrollments WHERE user_id = ? AND course_id = ? AND status = 'active'`
          ).bind(payload.sub, sessionCourse.course_id).first();
          const isFree = await env2.DB.prepare(
            `SELECT is_free FROM LiveSessions WHERE id = ?`
          ).bind(sessionId).first();
          if (isEnrolled || isFree && Number(isFree.is_free) === 1) {
            const attId = generateCustomId("YA-ATT");
            await env2.DB.prepare(
              `INSERT OR IGNORE INTO Attendance (id, session_id, user_id)
               VALUES (?, ?, ?)`
            ).bind(attId, sessionId, payload.sub).run();
          }
        }
      }
      return new Response(JSON.stringify({ success: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    if (request.method === "GET") {
      const lastPoll = url.searchParams.get("lastPoll") || "1970-01-01";
      const { results } = await env2.DB.prepare(
        `
        SELECT * FROM LiveSignaling
        WHERE session_id = ?
        AND created_at > ?
        AND user_id != ?
        ORDER BY created_at ASC
      `
      ).bind(sessionId, lastPoll, payload.sub).all();
      return new Response(JSON.stringify({ signals: results }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    if (request.method === "DELETE") {
      await env2.DB.prepare(
        'DELETE FROM LiveSignaling WHERE session_id = ? AND created_at < datetime("now", "-1 hour")'
      ).bind(sessionId).run();
      return new Response(JSON.stringify({ success: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    return new Response("Method not allowed", { status: 405 });
  } catch (error4) {
    return handleGlobalError(error4, "Live.Signaling", env2, request);
  }
}
