async function handleCreateSubscription(request, env2) {
  try {
    const payload = await requireAuth(request, env2);
    const { planId } = await request.json();
    const plan = await env2.DB.prepare(
      "SELECT * FROM SubscriptionPlans WHERE id = ? AND is_active = 1"
    ).bind(planId).first();
    if (!plan)
      return new Response(
        JSON.stringify({ error: "Subscription plan not found" }),
        { status: 404 }
      );
    if (!plan.razorpay_plan_id)
      return new Response(
        JSON.stringify({
          error: "This plan is not yet linked to Razorpay. Contact admin."
        }),
        { status: 503 }
      );
    const existingActiveSub = await env2.DB.prepare(
      `SELECT id FROM Subscriptions WHERE user_id = ? AND status IN ('active', 'authenticated') AND (current_period_end IS NULL OR current_period_end > datetime('now')) LIMIT 1`
    ).bind(payload.sub).first();
    if (existingActiveSub) {
      return new Response(
        JSON.stringify({
          error: "Aapke paas already ek active subscription hai. Pehle use cancel karke naya subscribe karein.",
          code: "ACTIVE_SUBSCRIPTION_EXISTS"
        }),
        { status: 409 }
      );
    }
    const razorpayKey = await getSecret(env2, "RAZORPAY_KEY_ID");
    const razorpaySecret = await getSecret(env2, "RAZORPAY_KEY_SECRET");
    if (!razorpayKey || !razorpaySecret) {
      return new Response(
        JSON.stringify({
          error: "Payment gateway is not configured.",
          code: "PAYMENT_NOT_CONFIGURED"
        }),
        { status: 503 }
      );
    }
    const user = await env2.DB.prepare(
      "SELECT email, full_name FROM Users WHERE id = ?"
    ).bind(payload.sub).first();
    const rzpBody = {
      plan_id: plan.razorpay_plan_id,
      total_count: 12,
      // Allow up to 12 billing cycles (auto-renews until cancelled)
      quantity: 1,
      customer_notify: 1,
      notes: { userId: payload.sub, planId }
    };
    const rzpRes = await fetch("https://api.razorpay.com/v1/subscriptions", {
      method: "POST",
      headers: {
        Authorization: "Basic " + btoa(`${razorpayKey}:${razorpaySecret}`),
        "Content-Type": "application/json"
      },
      body: JSON.stringify(rzpBody)
    });
    const rzpData = await rzpRes.json();
    if (!rzpRes.ok) {
      console.error("Razorpay subscription create error:", rzpData);
      return new Response(
        JSON.stringify({
          error: rzpData.error?.description || "Failed to create subscription"
        }),
        { status: 502 }
      );
    }
    const secondCheck = await env2.DB.prepare(
      `SELECT id FROM Subscriptions WHERE user_id = ? AND status IN ('active', 'authenticated') AND (current_period_end IS NULL OR current_period_end > datetime('now')) LIMIT 1`
    ).bind(payload.sub).first();
    if (secondCheck) {
      try {
        await fetch(`https://api.razorpay.com/v1/subscriptions/${rzpData.id}/cancel`, {
          method: "POST",
          headers: {
            Authorization: "Basic " + btoa(`${razorpayKey}:${razorpaySecret}`)
          }
        });
      } catch (_cancelErr) {
        console.error("Failed to cancel Razorpay subscription after race:", _cancelErr);
      }
      return new Response(
        JSON.stringify({
          error: "Aapke paas already ek active subscription hai. Pehle use cancel karke naya subscribe karein.",
          code: "ACTIVE_SUBSCRIPTION_EXISTS"
        }),
        { status: 409 }
      );
    }
    const subId = generateCustomId("YA-SUB");
    await env2.DB.prepare(
      "INSERT INTO Subscriptions (id, user_id, plan_id, razorpay_subscription_id, status, live_class_amount_rupees, is_lifetime) VALUES (?, ?, ?, ?, ?, ?, ?)"
    ).bind(subId, payload.sub, planId, rzpData.id, "created", plan.live_class_amount_rupees || 0, plan.is_lifetime || 0).run();
    if (user?.email) {
      const subject = `Your New Subscription: ${plan.name}`;
      const title2 = "Subscription Created";
      const htmlBody = `
        <p>Namaste <strong>${user.full_name || "Student"}</strong>,</p>
        <p>You have successfully initiated a new subscription: <strong>${plan.name}</strong>.</p>
        <div style="background: #f0fdf4; padding: 20px; border-radius: 12px; margin: 24px 0; border: 1px solid #bbf7d0;">
          <p style="margin: 0; color: #166534; font-weight: bold;">Subscription Details:</p>
          <p style="margin: 8px 0 0 0;">Plan: ${plan.name}</p>
          <p style="margin: 4px 0 0 0;">Amount: \u20B9${Math.round(plan.amount_rupees / 100)} / ${plan.interval}</p>
        </div>
        <p>Please complete the payment in the checkout window to activate your subscription.</p>
        <p style="font-size: 13px; color: #64748b;">If you closed the window, you can re-initiate the payment from your student dashboard.</p>
      `;
      const textBody = `Namaste ${user.full_name || "Student"},

Your new subscription for ${plan.name} has been created. Please complete the payment to activate it.

Amount: \u20B9${Math.round(plan.amount_rupees / 100)} / ${plan.interval}`;
      await safeSendEmail(env2, user.email, subject, title2, htmlBody, textBody);
    }
    return new Response(
      JSON.stringify({
        subscription_id: rzpData.id,
        key: razorpayKey,
        plan: { name: plan.name, amount_rupees: plan.amount_rupees },
        user: { email: user?.email, name: user?.full_name }
      }),
      { status: 200, headers: { "Content-Type": "application/json" } }
    );
  } catch (error4) {
    return handleGlobalError(error4, "Subscription.Create", env2, request);
  }
}
