async function handleCancelSubscription(request, env2) {
  try {
    const payload = await requireAuth(request, env2);
    const sub = await env2.DB.prepare(
      `SELECT * FROM Subscriptions WHERE user_id = ? AND status IN ('active','authenticated','created') ORDER BY created_at DESC LIMIT 1`
    ).bind(payload.sub).first();
    if (!sub)
      return new Response(
        JSON.stringify({ error: "No active subscription found" }),
        { status: 404 }
      );
    const isCreatedStatus = sub.status === "created";
    if (!isCreatedStatus) {
      const razorpayKey = await getSecret(env2, "RAZORPAY_KEY_ID");
      const razorpaySecret = await getSecret(env2, "RAZORPAY_KEY_SECRET");
      if (razorpayKey && razorpaySecret && sub.razorpay_subscription_id) {
        const rzpCancelRes = await fetch(
          `https://api.razorpay.com/v1/subscriptions/${sub.razorpay_subscription_id}/cancel`,
          {
            method: "POST",
            headers: {
              Authorization: "Basic " + btoa(`${razorpayKey}:${razorpaySecret}`),
              "Content-Type": "application/json"
            },
            body: JSON.stringify({ cancel_at_cycle_end: 1 })
          }
        );
        if (!rzpCancelRes.ok) {
          const rzpErr = await rzpCancelRes.json();
          console.error("[Cancel] Razorpay cancel failed:", rzpErr);
          return new Response(
            JSON.stringify({
              error: rzpErr.error?.description || "Razorpay par cancel fail ho gaya. Baad mein try karein."
            }),
            { status: 502 }
          );
        }
      }
    }
    await env2.DB.prepare("UPDATE Subscriptions SET status = ? WHERE id = ?").bind("cancelled", sub.id).run();
    await createNotification(
      env2,
      payload.sub,
      "Subscription Cancelled",
      "Aapka subscription cancel ho gaya hai. Access period end tak active rahega.",
      "info"
    );
    return new Response(
      JSON.stringify({
        success: true,
        message: "Subscription cancelled. Access will remain until end of current period."
      }),
      { status: 200 }
    );
  } catch (error4) {
    return handleGlobalError(error4, "Subscription.Cancel", env2, request);
  }
}
__name(handleCancelSubscription, "handleCancelSubscription");
async function handleAdminPlanPool(request, env2, planId) {
  try {
    await requireAdmin(request, env2);
    if (request.method === "GET") {
      const { results } = await env2.DB.prepare(
        `SELECT pcp.*, c.title as course_title, b.name as batch_name, bo.title as book_title
         FROM PlanContentPool pcp
         LEFT JOIN Courses c ON pcp.item_type = 'course' AND pcp.item_id = c.id
         LEFT JOIN Batches b ON pcp.item_type = 'batch' AND pcp.item_id = b.id
         LEFT JOIN Books bo ON pcp.item_type = 'book' AND pcp.item_id = bo.id
         WHERE pcp.plan_id = ? ORDER BY pcp.item_type, pcp.access_mode`
      ).bind(planId).all();
      return new Response(JSON.stringify({ pool: results }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    if (request.method === "POST") {
      const items = await request.json();
      if (!Array.isArray(items) || items.length === 0) {
        return new Response(JSON.stringify({ error: "items array required" }), {
          status: 400
        });
      }
      const stmts = items.map(
        (item) => env2.DB.prepare(
          `INSERT OR REPLACE INTO PlanContentPool (id, plan_id, item_type, item_id, access_mode, bonus_ai_credits)
           VALUES (?, ?, ?, ?, ?, ?)`
        ).bind(
          generateCustomId("YA-PCP"),
          planId,
          item.item_type,
          item.item_id,
          item.access_mode,
          item.bonus_ai_credits || 0
        )
      );
      await env2.DB.batch(stmts);
      return new Response(
        JSON.stringify({ success: true, added: items.length }),
        { status: 201, headers: { "Content-Type": "application/json" } }
      );
    }
    if (request.method === "DELETE") {
      const { item_type, item_id } = await request.json();
      await env2.DB.prepare(
        "DELETE FROM PlanContentPool WHERE plan_id = ? AND item_type = ? AND item_id = ?"
      ).bind(planId, item_type, item_id).run();
      return new Response(JSON.stringify({ success: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    return new Response("Method not allowed", { status: 405 });
  } catch (error4) {
    if (error4.message === "Unauthorized" || error4.message === "Forbidden" || error4.message === "Token expired")
      return new Response(JSON.stringify({ error: error4.message }), {
        status: error4.message === "Forbidden" ? 403 : 401
      });
    return handleGlobalError(error4, "Admin.PlanPool", env2, request);
  }
}
