async function getAiModelConfig(env2, modelId) {
  const db = env2.DB;
  let model = null;
  if (modelId) {
    model = await db.prepare("SELECT * FROM AiModels WHERE id = ? AND is_active = 1").bind(modelId).first();
  }
  if (!model) {
    model = await db.prepare("SELECT * FROM AiModels WHERE is_default = 1 AND is_active = 1").first();
  }
  if (!model) {
    return [{
      id: "@cf/meta/llama-3.1-8b-instruct",
      name: "Meta Llama 3.1 8B",
      provider: "workers-ai",
      endpoint: "chat/completions",
      is_active: 1,
      is_default: 1
    }];
  }
  const models = [model];
  if (model.fallback_model_ids) {
    try {
      const fallbackIds = JSON.parse(model.fallback_model_ids);
      for (const fId of fallbackIds) {
        const fallback = await db.prepare("SELECT * FROM AiModels WHERE id = ? AND is_active = 1").bind(fId).first();
        if (fallback) models.push(fallback);
      }
    } catch (e) {
      console.error("Failed to parse fallback_model_ids", e);
    }
  }
  return models;
}
