async function handleGetChatHistory(request, env2) {
  try {
    const token = getCookie(request, "session");
    if (!token)
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401
      });
    const jwtSecret = await getSecret(env2, "JWT_SECRET");
    if (!jwtSecret) throw new Error("JWT_SECRET missing");
    const payload = await verifyJWT(token, jwtSecret, env2.ENVIRONMENT);
    const userId = payload.sub;
    const url = new URL(request.url);
    const sessionId = url.searchParams.get("sessionId");
    let records;
    if (sessionId) {
      records = await env2.DB.prepare(
        "SELECT role, content, created_at FROM ChatHistory WHERE user_id = ? AND session_id = ? ORDER BY created_at ASC LIMIT 50"
      ).bind(userId, sessionId).all();
    } else {
      records = await env2.DB.prepare(
        "SELECT role, content, created_at FROM ChatHistory WHERE user_id = ? ORDER BY created_at ASC LIMIT 50"
      ).bind(userId).all();
    }
    return new Response(JSON.stringify(records.results), {
      status: 200,
      headers: { "Content-Type": "application/json" }
    });
  } catch (error4) {
    return handleGlobalError(error4, "AI.GetHistory", env2, request);
  }
}
